#!/usr/bin/env python3
"""Bygg metodrapportens aktuella resultat från sparad OCR-export."""
import argparse,datetime,html,json,re
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('corpus',type=Path);a=p.parse_args();root=Path(__file__).resolve().parents[1];site=root/'docs';docs=json.loads((site/'assets/pilot.js').read_text().split(' = ',1)[1].rstrip(';\n'))['documents'];quality=json.loads((site/'ocr-quality.json').read_text());progress=json.loads((a.corpus/'04_metadata/ocr_batch_progress.json').read_text());benchmark=json.loads((site/'ocr-benchmark.json').read_text());corefile=a.corpus/'04_metadata/ocr_core_progress.json';core=json.loads(corefile.read_text()) if corefile.exists() else {};coreCandidates=list((a.corpus/'02_ocr/tesseract-core-v4').glob('*/*.json'));core=dict(version='core-v4',available=len(coreCandidates),planned=core.get('planned',218),latestRun=core if core.get('updatedAt','')>=progress['startedAt'] else None);now=datetime.datetime.now(datetime.timezone.utc).isoformat();totals=dict(pdfDocuments=len(docs),pdfPages=sum(d['pages'] for d in docs),rawTextPages=sum(d['rawTextPages'] for d in docs),searchTextPages=sum(d['textPages'] for d in docs),**quality['stats']);totals['remainingWithoutSearchText']=totals['pdfPages']-totals['searchTextPages'];archive=a.corpus/'04_metadata/ocr_runs_before_statistics_fix';history=[json.loads(f.read_text()) for f in sorted(archive.glob('*.json'))] if archive.exists() else []
