(site/'bulk-processing.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');(a.corpus/'04_metadata/bulk_processing_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
f=lambda n:format(n,',').replace(',',' ')
rows=[('PDF-sidor kontrollerade och grundextraherade',totals['pdfPages']),('Sidor med ursprungligt textlager',totals['rawTextPages']),('Sidor med ny OCR-kandidat',totals['processed']),('Nya OCR-kandidater som passerade söktextregeln',totals['chosen']),('Tidigare textlösa sidor som fått söktext',totals['filled']),('Sidor med söktext efter bearbetningen',totals['searchTextPages']),('Sidor utan vald söktext',totals['remainingWithoutSearchText']),('OCR-sidor med maskinsäkerhet under 85',totals['lowConfidence'])]
